import {SETTLEMENT_NOTICE,BONUS_TYPES} from './bonus.js';
export function bonusHighlights(r,{amount,stat,warning}){const a=r.accrual[0],n=r.period.end-r.period.start+1;return `<div class="highlights"><article class="highlight"><div class="period">실적연도 발생 기준 · OPI1+OPI2</div><h2>${r.period.start}년도 총성과급은?</h2><div class="hero-label">세후 총성과급 예상</div><div class="hero-number">${amount(a.netTotal)}</div><div class="stats">${stat('세전 총성과급',amount(a.grossTotal))}${stat('OPI1 세후',amount(a.net.opi1),'cash')}${stat('OPI2 세후 전체 가치',amount(a.net.opi2),'stock')}${stat('자사주 지급가치',amount(a.netStock),'stock')}</div><div class="foot">월급·수당·TAI·PSU 제외. 실제 지급·매도 가능 시점과 관계없이 실적연도에 발생한 OPI1+OPI2 가치이며 예상 정산 차액을 포함합니다. 현재 쓸 수 있는 현금과 다릅니다.</div>${warning()}</article><article class="highlight"><div class="period">${r.period.start}–${r.period.end} · ${n}개년 OPI1+OPI2</div><h2>앞으로 ${n}년간 총성과급은?</h2><div class="hero-label">기간 내 현금화 · 예상 정산 반영 후</div><div class="hero-number cash">${amount(r.totals.netLiquid)}</div><div class="stats three">${stat('정산 반영 전 현금화',amount(r.totals.netLiquidBeforeSettlement))}${stat('세금 정산 순유입 (+/−)',amount(r.totals.taxSettlementInPeriod),'cash')}${stat('보험 차액 (+/−)',amount(r.totals.insuranceSettlementInPeriod))}${stat('세전 발생 총성과급',amount(r.totals.grossAccrual))}${stat('세후 발생 총성과급',amount(r.totals.netAccrual))}${stat('연평균 세후 발생',amount(Math.round(r.totals.netAccrual/n)))}</div><div class="foot">정산 전 + 세금 정산 차액 + 보험 차액 = 반영 후 현금화. 세금 환급/추가납부는 과세 다음 해 2월 계산용 가정입니다. 삼성 확정 입금일이 아니며 주식 해제와 별개입니다.</div>${warning()}</article></div>`;}
export function bonusTable(r,basis,{amount,escape:esc}){
 const rows=basis==='accrual'?r.accrual:r.cashflow;let cumulativeAccrual=0;
 const heads=basis==='accrual'?['실적연도','OPI1 세전','OPI2 세전','세전 연간 총성과급','OPI1 세후','OPI2 세후','세후 연간 총성과급','누적 세후 발생']:['지급·현금화연도','수령 OPI1 세후','매각 가능 OPI2','정산 전 연간','세금 환급/추가납부 (+/−)','보험 정산 차액 (+/−)','정산 후 연간','정산 후 누적'];
 return '<div class="table-wrap"><table><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(a=>{cumulativeAccrual+=basis==='accrual'?a.netTotal:0;const values=basis==='accrual'?[a.gross.opi1,a.gross.opi2,a.grossTotal,a.net.opi1,a.net.opi2,a.netTotal,cumulativeAccrual]:[a.net.opi1,a.net.opi2,a.netBeforeSettlement,a.taxSettlement,a.insuranceSettlement,a.netTotal,a.cumulative];return '<tr><td><strong>'+a.year+'</strong>'+(basis==='accrual'?a.reasons.filter(x=>/미달|미지급/.test(x)).map(x=>'<div class="reason">'+esc(x)+'</div>').join(''):'')+'</td>'+values.map(v=>'<td>'+amount(v)+'</td>').join('')+'</tr>';}).join('')+'</tbody></table></div><p class="disclosure">'+(basis==='accrual'?'성과를 낸 실적연도 기준. 세후 발생액에는 그 보상에 배분한 예상 정산 차액을 포함하므로 지급·매각 가능한 현금과 다릅니다.':'현금 유입연도 기준. 세금 정산은 +면 환급 예상, −면 추가납부 예상이며 소득세·지방소득세를 포함합니다. 보험은 별도 차액입니다. 주식 1/3 매각액에는 환급을 다시 더하지 않습니다.')+'</p>';
}
export function settlementDetails(r,{amount,escape:esc,warning}){
 return `<section class="panel" id="settlement-explanation"><h3>예상 환급은 언제 반영되나요?</h3><p class="disclosure">2026년 실적 → 2027년 지급·소득 귀속 가정 → 2028년 2월 세금 정산 가정. 보험은 다음 해 4월 별도 차액 정산 가정입니다. 실제 삼성 입금일은 확인되지 않았습니다.</p><details><summary>선징수·누진세·환급과 주식의 관계</summary><p class="disclosure">${esc(SETTLEMENT_NOTICE)} 기부 세액공제는 계산하지 않습니다.</p><div class="table-wrap"><table><thead><tr><th>실적연도</th><th>지급·소득 귀속 가정</th><th>선징수 소득세·지방세</th><th>최종 증분 세금 추정</th><th>세금 정산 가정 (+/−)</th><th>보험 차액 가정 (+/−)</th></tr></thead><tbody>${r.events.filter(e=>e.type==='opi2').map(e=>`<tr><td>${e.origin}</td><td>${e.payYear}년</td><td>${amount(e.snapshot.withheldTax)}</td><td>${amount(e.finalTaxEstimate)}</td><td>${e.settlements.find(t=>t.kind==='tax').year}년 2월 / ${amount(e.identity.settlementTax)}</td><td>${e.settlements.find(t=>t.kind==='insurance').year}년 4월 / ${amount(e.identity.settlementInsurance)}</td></tr>`).join('')}</tbody></table></div><p class="disclosure">국세청이 회사에 지급하는 환급일과 회사가 직원에게 지급하는 날은 다릅니다. 지급일만으로 성과급 소득 귀속을 일반화하지 않습니다. <a href="https://www.nts.go.kr/nts/cm/cntnts/cntntsView.do?cntntsId=7702&mi=2312" target="_blank" rel="noopener">국세청 연말정산 참고</a> · <a href="https://www.nts.go.kr/nts/na/ntt/selectNttInfo.do?mi=2163&nttSn=1349564" target="_blank" rel="noopener">국세청 2026 환급 안내</a></p></details>${warning()}</section>`;
}
export function fullSummary(r,{amount,warning}){const f=r.fullCompensation;return `<section class="panel" id="full-compensation-summary"><h3>마지막 별도 요약 · 월급 포함 전체 보상</h3><p class="disclosure">이 영역만 월급·고정수당·TAI·PSU를 포함합니다. 이 항목들은 위 총성과급 합계에서 제외되며 연간 소득 합산 세금 계산에는 포함됩니다.</p><div class="grid three">${['세전 발생 총보상','세후 발생 총보상','전체 현금화 가능액'].map((label,i)=>`<div class="mini-card"><div class="muted">${label}</div><div class="big">${amount([f.totals.grossAccrual,f.totals.netAccrual,f.totals.netLiquid][i])}</div></div>`).join('')}</div><details><summary>연도별 월급·일반보상·PSU 포함 내역</summary><div class="table-wrap"><table><thead><tr><th>연도</th><th>계약연봉</th><th>세후 월급·수당</th><th>수령 TAI 세후</th><th>매각 PSU 세후</th><th>전체 세후 발생</th><th>전체 현금화</th></tr></thead><tbody>${f.accrual.map((a,i)=>`<tr><td>${a.year}</td><td>${amount(a.salary)}</td><td>${amount(f.cashflow[i].net.salary)}</td><td>${amount(f.cashflow[i].net.tai)}</td><td>${amount(f.cashflow[i].net.psu)}</td><td>${amount(a.netTotal)}</td><td>${amount(f.cashflow[i].netTotal)}</td></tr>`).join('')}</tbody></table></div></details>${warning()}</section>`;}
